import{_ as e,o as t,c as r,ag as n}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"安装并进入平台","description":"按顺序完成中心安装、默认组织首次设置和工作台登录。","frontmatter":{"title":"安装并进入平台","description":"按顺序完成中心安装、默认组织首次设置和工作台登录。","status":"reviewed","kind":"tutorial"},"headers":[],"relativePath":"zh/start/index.md","filePath":"zh/快速开始/安装并进入平台.md"}'),i={name:"zh/start/index.md"};function o(l,a,h,s,d,p){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="安装并进入平台" tabindex="-1">安装并进入平台 <a class="header-anchor" href="#安装并进入平台" aria-label="Permalink to &quot;安装并进入平台&quot;">​</a></h1><p>这条教程带你在准备好的 Linux 服务器上安装 InduFrame 中心，随后通过浏览器进入默认组织的工作台。完成后，你应能登录、打开工程管理、刷新页面并正常退出。</p><p>你需要服务器的系统管理权限、匹配架构的完整安装包，以及能够访问服务器的浏览器。首次安全设置由平台超级管理员完成，组织管理员随后从公共入口登录。若平台已经安装并完成设置，可直接阅读<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>。</p><h2 id="_1-准备服务器和访问地址" tabindex="-1">1. 准备服务器和访问地址 <a class="header-anchor" href="#_1-准备服务器和访问地址" aria-label="Permalink to &quot;1. 准备服务器和访问地址&quot;">​</a></h2><p>先核对<a href="/induframe-docs/zh/installation/prepare.html">安装前准备</a>：操作系统、剩余磁盘空间、访问地址、端口和证书。保留完整安装包，确认目标服务器就是本次安装对象。</p><p><strong>完成标志</strong>：安装所需材料齐全，浏览器可以到达计划使用的服务器网络。</p><h2 id="_2-安装中心" tabindex="-1">2. 安装中心 <a class="header-anchor" href="#_2-安装中心" aria-label="Permalink to &quot;2. 安装中心&quot;">​</a></h2><p>在完整包目录执行安装入口，按提示填写存放位置、公共地址、端口、平台超级管理员和证书配置。具体步骤与默认值见<a href="/induframe-docs/zh/installation/install.html">安装中心</a>。</p><p><strong>完成标志</strong>：终端显示“InduFrame 中心安装完成。”，安装进程正常结束，并给出公共入口、管理入口和日志路径。</p><h2 id="_3-完成首次设置" tabindex="-1">3. 完成首次设置 <a class="header-anchor" href="#_3-完成首次设置" aria-label="Permalink to &quot;3. 完成首次设置&quot;">​</a></h2><p>从管理入口登录，在“组织管理”为默认组织管理员设置密码，再打开公共入口。两个入口的操作见<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>。</p><p><strong>完成标志</strong>：出现“管理员密码已重置”反馈，公共入口开放，组织管理员能使用新密码登录。</p><h2 id="_4-确认安装成功" tabindex="-1">4. 确认安装成功 <a class="header-anchor" href="#_4-确认安装成功" aria-label="Permalink to &quot;4. 确认安装成功&quot;">​</a></h2><p>按<a href="/induframe-docs/zh/installation/verify.html">确认安装成功</a>核对终端、管理入口和组织工作台。打开工程管理，刷新后确认仍可访问，再退出并确认受保护页面需要重新登录。</p><p><strong>完成标志</strong>：这些检查都有明确结果。工程部署还需要单独准备运行环境的基础服务，安装完成不代表工程已经投入运行。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>停在当前失败步骤，保留提示和时间，根据<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>先核对可观察条件。未出现安装完成提示时，不要直接转入首次设置，也不要以删除数据或反复重装代替排查。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>保存两个入口地址与账号交接信息，日常使用从<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>开始。需要停用时，先了解<a href="/induframe-docs/zh/installation/uninstall.html">卸载平台</a>中两种方式对数据的影响。</p>',19)])])}const _=e(i,[["render",o]]);export{c as __pageData,_ as default};
